<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('administrador');$pageTitle='Servicios';$errors=[];$current=null;$categories=db()->query("SELECT id,nombre FROM categorias WHERE tipo='servicio' ORDER BY nombre")->fetchAll();if(isset($_GET['t'])){$id=decode_id($_GET['t']);if(!$id)abort_forbidden('Token alterado.');$s=db()->prepare('SELECT * FROM servicios WHERE id=?');$s->execute([$id]);$current=$s->fetch();}
if(request_is_post()){verify_csrf();$fa=clean_text($_POST['form_action']??'',20);if(in_array($fa,['create','update'],true)){$name=clean_text($_POST['nombre']??'',140);$description=clean_multiline($_POST['descripcion']??'',4000);$cat=filter_input(INPUT_POST,'categoria_id',FILTER_VALIDATE_INT)?:null;$price=filter_input(INPUT_POST,'precio_desde',FILTER_VALIDATE_FLOAT);$order=filter_input(INPUT_POST,'orden',FILTER_VALIDATE_INT)?:0;$active=isset($_POST['activo'])?1:0;if(mb_strlen($name)<3)$errors[]='Nombre inválido.';if(mb_strlen($description)<10)$errors[]='Agrega una descripción.';if(!$errors){if($fa==='create'){db()->prepare('INSERT INTO servicios(categoria_id,nombre,slug,descripcion,precio_desde,orden,activo)VALUES(?,?,?,?,?,?,?)')->execute([$cat,$name,slugify($name).'-'.bin2hex(random_bytes(2)),$description,$price!==false?$price:null,$order,$active]);flash('success','Servicio creado.');}else{$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');db()->prepare('UPDATE servicios SET categoria_id=?,nombre=?,descripcion=?,precio_desde=?,orden=?,activo=?,updated_at=NOW() WHERE id=?')->execute([$cat,$name,$description,$price!==false?$price:null,$order,$active,$id]);flash('success','Servicio actualizado.');}redirect('admin/servicios.php');}}if($fa==='delete'){$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');db()->prepare('DELETE FROM servicios WHERE id=?')->execute([$id]);flash('success','Servicio eliminado.');redirect('admin/servicios.php');}}
$items=db()->query('SELECT s.*,c.nombre categoria FROM servicios s LEFT JOIN categorias c ON c.id=s.categoria_id ORDER BY s.orden,s.nombre')->fetchAll();require dirname(__DIR__).'/includes/admin_header.php';
?>
<div class="panel-heading"><div><h1>Servicios</h1><p>CRUD del catálogo público de RootCode.</p></div></div><div class="grid-2"><form class="card" method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="<?=$current?'update':'create'?>"><?php if($current):?><input type="hidden" name="token_id" value="<?=e(encode_id((int)$current['id']))?>"><?php endif;?><h2><?=$current?'Editar servicio':'Nuevo servicio'?></h2><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as$er):?><li><?=e($er)?></li><?php endforeach;?></ul></div><?php endif;?><div class="field"><label>Nombre</label><input name="nombre" value="<?=e($current['nombre']??'')?>" required></div><div class="field"><label>Categoría</label><select name="categoria_id"><option value="">Sin categoría</option><?php foreach($categories as$c):?><option value="<?=(int)$c['id']?>" <?=($current['categoria_id']??null)==$c['id']?'selected':''?>><?=e($c['nombre'])?></option><?php endforeach;?></select></div><div class="field"><label>Descripción</label><textarea name="descripcion" required><?=e($current['descripcion']??'')?></textarea></div><div class="form-grid"><div class="field"><label>Precio desde</label><input type="number" step="0.01" min="0" name="precio_desde" value="<?=e(isset($current['precio_desde'])?(string)$current['precio_desde']:'')?>"></div><div class="field"><label>Orden</label><input type="number" name="orden" value="<?=e(isset($current['orden'])?(string)$current['orden']:'0')?>"></div></div><label><input type="checkbox" name="activo" style="width:auto" <?=!$current||$current['activo']?'checked':''?>> Activo</label><div class="actions"><button class="btn">Guardar</button><?php if($current):?><a class="btn btn-light" href="<?=url('admin/servicios.php')?>">Cancelar</a><?php endif;?></div></form><div class="table-card"><div class="table-responsive"><table><thead><tr><th>Servicio</th><th>Precio</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($items as$it):?><tr><td><strong><?=e($it['nombre'])?></strong><br><small><?=e($it['categoria']??'Sin categoría')?></small></td><td><?=$it['precio_desde']!==null?format_money($it['precio_desde']):'—'?></td><td><span class="badge badge-<?=$it['activo']?'success':'danger'?>"><?=$it['activo']?'Activo':'Inactivo'?></span></td><td class="table-actions"><a class="btn btn-small btn-light" href="<?=url('admin/servicios.php?t='.encode_id((int)$it['id']))?>">Editar</a><form method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="token_id" value="<?=e(encode_id((int)$it['id']))?>"><button class="btn btn-small btn-danger" data-confirm="¿Eliminar este servicio?">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div>
<?php require dirname(__DIR__).'/includes/admin_footer.php';?>
